package com.malikoil.intelligence
object MandiMessageIndex{
 const val DEFAULT_PRIORITIES="Samundri, Faisalabad, Gojra, Toba Tek Singh, Tandlianwala, Jaranwala, Dijkot"
 private val aliases=linkedMapOf(
 "Samundri" to listOf("Samundri","Samundari","سمندری"),"Faisalabad" to listOf("Faisalabad","FSD","فیصل آباد","فیصل آباد"),"Gojra" to listOf("Gojra","گوجرہ"),"Toba Tek Singh" to listOf("Toba Tek Singh","Toba","ٹوبہ ٹیک سنگھ"),"Tandlianwala" to listOf("Tandlianwala","تاندلیانوالہ"),"Jaranwala" to listOf("Jaranwala","جڑانوالہ"),"Dijkot" to listOf("Dijkot","ڈجکوٹ"),"Lahore" to listOf("Lahore","لاہور"),"Multan" to listOf("Multan","ملتان"),"Jhang" to listOf("Jhang","جھنگ"),"Chiniot" to listOf("Chiniot","چنیوٹ"),"Sargodha" to listOf("Sargodha","سرگودھا"),"Sahiwal" to listOf("Sahiwal","ساہیوال"),"Okara" to listOf("Okara","اوکاڑہ"),"Gujranwala" to listOf("Gujranwala","گوجرانوالہ"),"Gujrat" to listOf("Gujrat","گجرات"),"Bahawalpur" to listOf("Bahawalpur","بہاولپور"),"Bahawalnagar" to listOf("Bahawalnagar","بہاولنگر"),"Rahim Yar Khan" to listOf("Rahim Yar Khan","رحیم یار خان"),"Vehari" to listOf("Vehari","وہاڑی"),"Khanewal" to listOf("Khanewal","خانیوال"),"Arifwala" to listOf("Arifwala","عارف والا","عارفوالہ"),"Burewala" to listOf("Burewala","بورے والا"),"Pakpattan" to listOf("Pakpattan","پاکپتن"),"Kasur" to listOf("Kasur","قصور"),"Sheikhupura" to listOf("Sheikhupura","شیخوپورہ"),"Nankana Sahib" to listOf("Nankana Sahib","ننکانہ صاحب"),"Hafizabad" to listOf("Hafizabad","حافظ آباد"),"Mandi Bahauddin" to listOf("Mandi Bahauddin","منڈی بہاؤالدین"),"Mianwali" to listOf("Mianwali","میانوالی"),"Rawalpindi" to listOf("Rawalpindi","راولپنڈی"),"Attock" to listOf("Attock","اٹک"),"Chakwal" to listOf("Chakwal","چکوال"),"Jhelum" to listOf("Jhelum","جہلم"),"Dera Ghazi Khan" to listOf("Dera Ghazi Khan","DG Khan","ڈیرہ غازی خان"),"Layyah" to listOf("Layyah","لیہ"),"Muzaffargarh" to listOf("Muzaffargarh","مظفرگڑھ"),"Lodhran" to listOf("Lodhran","لودھراں"),"Kamalia" to listOf("Kamalia","کمالیہ"),"Pir Mahal" to listOf("Pir Mahal","پیر محل"),"Sialkot" to listOf("Sialkot","سیالکوٹ"),"Narowal" to listOf("Narowal","نارووال"))
 private fun pattern(names:List<String>)=Regex("(?<![\\p{L}\\p{N}])(?:"+names.joinToString("|"){Regex.escape(it)}+")(?![\\p{L}\\p{N}])",RegexOption.IGNORE_CASE)
 private val patterns=aliases.mapValues{pattern(it.value)}
 private val sarson=pattern(listOf("sarson","sarso","sarsoon","sarsoo","mustard","mustard seed","سرسوں"))
 private val nonSeed=Regex("mustard\\s+(oil|greens)|sarson\\s+(oil|ka\\s+tail)|سرسوں\\s+کا\\s+تیل|ساگ",RegexOption.IGNORE_CASE)
 fun sarsonMention(text:String)=text.lineSequence().any{line->sarson.containsMatchIn(line)&&!nonSeed.containsMatchIn(line)}
 fun priorities(value:String):List<String>{require(value.length<=400);return value.split(',','،').map{it.trim()}.filter{it.isNotEmpty()}.map{name->aliases.entries.find{entry->entry.value.any{it.equals(name,true)}}?.key?:name}.distinct().take(15)}
 fun cities(text:String,priorities:List<String> = emptyList()):List<String>{val known=patterns.filterValues{it.containsMatchIn(text)}.keys.toList();return (known+priorities.filter{it !in aliases&&pattern(listOf(it)).containsMatchIn(text)}).distinct()}
 fun rank(cities:List<String>,priorities:List<String>)=priorities.indices.firstOrNull{priorities[it] in cities}?:Int.MAX_VALUE
}
